<script>document.addEventListener('DOMContentLoaded',()=>{const audience=document.querySelector('[data-notice-audience]'),wrap=document.querySelector('[data-notice-target]'),target=document.getElementById('target_id');function update(){const type=audience.value;wrap.hidden=type==='all';target.required=type!=='all';for(const option of target.querySelectorAll('[data-audience-target]'))option.hidden=option.dataset.audienceTarget!==type;if(type==='all')target.value='';}audience.addEventListener('change',update);update();});</script>
